// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.Customer;
using Shared.DTO.Departments;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Department
{
    public partial class Edit
    {

        [Parameter]
        public string id { get; set; }

        DepartmentDto department { get; set; } = new DepartmentDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected async override Task OnInitializedAsync()
        {
            department = await Http.GetFromJsonAsync<DepartmentDto>("api/Departments/" + id);
        }

        protected async Task EditDepartment()
        {
            var response = await Http.PutAsJsonAsync("api/Departments/"+id, department);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Department");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }

        }
    }
}
